create extension if not exists pgcrypto;create table if not exists items(id uuid primary key default gen_random_uuid(),type text not null check(type in('album','book','article','product')),state text not null default 'queued' check(state in('queued','tried','loved','dropped')),title text not null,creator text,external_url text,external_id text,image_url text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());create unique index if not exists items_type_external_id on items(type,external_id) where external_id is not null;
